# porta de src/pk112.inc (nomes 1.12.2 -> canonicos)
def _color(c): return 'light_gray' if c=='silver' else c
def _wood(w): return 'dark_oak' if w in ('big_oak','roofed_oak') else 'oak' if w=='wood' else w
M={'hardened_clay': 'terracotta', 'stone_granite': 'granite', 'stone_granite_smooth': 'polished_granite', 'stone_diorite': 'diorite', 'stone_diorite_smooth': 'polished_diorite', 'stone_andesite': 'andesite', 'stone_andesite_smooth': 'polished_andesite', 'stonebrick': 'stone_bricks', 'stonebrick_carved': 'chiseled_stone_bricks', 'stonebrick_cracked': 'cracked_stone_bricks', 'stonebrick_mossy': 'mossy_stone_bricks', 'sandstone_carved': 'chiseled_sandstone', 'sandstone_smooth': 'cut_sandstone', 'red_sandstone_carved': 'chiseled_red_sandstone', 'red_sandstone_smooth': 'cut_red_sandstone', 'red_sandstone_normal': 'red_sandstone', 'sandstone_normal': 'sandstone', 'end_bricks': 'end_stone_bricks', 'nether_brick': 'nether_bricks', 'red_nether_brick': 'red_nether_bricks', 'ice_packed': 'packed_ice', 'magma': 'magma_block', 'dirt_podzol_top': 'podzol_top', 'dirt_podzol_side': 'podzol_side', 'redstone_lamp_off': 'redstone_lamp', 'quartz_block_lines': 'quartz_pillar', 'quartz_block_lines_top': 'quartz_pillar_top', 'prismarine_dark': 'dark_prismarine', 'prismarine_rough': 'prismarine', 'mushroom_block_skin_brown': 'brown_mushroom_block', 'mushroom_block_skin_red': 'red_mushroom_block', 'mushroom_block_skin_stem': 'mushroom_stem', 'mushroom_block_inside': 'mushroom_block_inside', 'reeds': 'sugar_cane', 'tallgrass': 'grass', 'deadbush': 'dead_bush', 'web': 'cobweb', 'waterlily': 'lily_pad', 'mob_spawner': 'spawner', 'noteblock': 'note_block', 'trapdoor': 'oak_trapdoor', 'flower_rose': 'poppy', 'flower_dandelion': 'dandelion', 'flower_houstonia': 'azure_bluet', 'flower_oxeye_daisy': 'oxeye_daisy', 'flower_allium': 'allium', 'flower_blue_orchid': 'blue_orchid', 'flower_tulip_red': 'red_tulip', 'flower_tulip_orange': 'orange_tulip', 'flower_tulip_pink': 'pink_tulip', 'flower_tulip_white': 'white_tulip', 'flower_paeonia': 'peony', 'double_plant_rose_bottom': 'rose_bush_bottom', 'double_plant_rose_top': 'rose_bush_top', 'double_plant_paeonia_bottom': 'peony_bottom', 'double_plant_paeonia_top': 'peony_top', 'double_plant_syringa_bottom': 'lilac_bottom', 'double_plant_syringa_top': 'lilac_top', 'double_plant_grass_bottom': 'tall_grass_bottom', 'double_plant_grass_top': 'tall_grass_top', 'double_plant_fern_bottom': 'large_fern_bottom', 'double_plant_fern_top': 'large_fern_top', 'double_plant_sunflower_bottom': 'sunflower_bottom', 'double_plant_sunflower_top': 'sunflower_top', 'double_plant_sunflower_front': 'sunflower_front', 'double_plant_sunflower_back': 'sunflower_back', 'sapling_oak': 'oak_sapling', 'sapling_spruce': 'spruce_sapling', 'sapling_birch': 'birch_sapling', 'sapling_jungle': 'jungle_sapling', 'sapling_acacia': 'acacia_sapling', 'sapling_roofed_oak': 'dark_oak_sapling', 'rail_normal': 'rail', 'rail_normal_turned': 'rail_corner', 'rail_golden': 'powered_rail', 'rail_golden_powered': 'powered_rail_on', 'rail_detector': 'detector_rail', 'rail_detector_powered': 'detector_rail_on', 'rail_activator': 'activator_rail', 'rail_activator_powered': 'activator_rail_on', 'melon_stem_connected': 'attached_melon_stem', 'melon_stem_disconnected': 'melon_stem', 'pumpkin_stem_connected': 'attached_pumpkin_stem', 'pumpkin_stem_disconnected': 'pumpkin_stem', 'redstone_torch_on': 'redstone_torch', 'redstone_torch_off': 'redstone_torch_off', 'torch_on': 'torch', 'anvil_base': 'anvil', 'grass_path_top': 'grass_path_top', 'slime': 'slime_block', 'cactus_bottom': 'cactus_bottom', 'soul_sand': 'soul_sand', 'hopper_outside': 'hopper_outside', 'dispenser_front_horizontal': 'dispenser_front', 'dropper_front_horizontal': 'dropper_front', 'piston_top_normal': 'piston_top', 'enchanting_table_top': 'enchanting_table_top', 'iron_bars': 'iron_bars', 'comparator_off': 'comparator', 'repeater_off': 'repeater', 'farmland_dry': 'farmland', 'farmland_wet': 'farmland_moist', 'portal': 'nether_portal', 'trip_wire': 'tripwire', 'trip_wire_source': 'tripwire_hook', 'wheat_stage_7': 'wheat_stage7', 'sponge_wet': 'wet_sponge', 'log_oak': 'oak_log', 'log_oak_top': 'oak_log_top', 'leaves_oak': 'oak_leaves', 'door_wood_lower': 'oak_door_bottom', 'door_wood_upper': 'oak_door_top', 'door_iron_lower': 'iron_door_bottom', 'door_iron_upper': 'iron_door_top', 'planks_oak': 'oak_planks', 'planks_big_oak': 'dark_oak_planks', 'brick': 'bricks', 'cobblestone_mossy': 'mossy_cobblestone'}
def pk112(n):
    if n in M: return M[n]
    if n.startswith('planks_'): return _wood(n[7:])+'_planks'
    if n.startswith('leaves_'): return _wood(n[7:])+'_leaves'
    if n.startswith('log_'):
        r=n[4:]; top=r.endswith('_top')
        if top: r=r[:-4]
        return _wood(r)+'_log'+('_top' if top else '')
    if n.startswith('door_'):
        r=n[5:]; up=r.endswith('_upper'); k=r.rfind('_')
        if k>=0: return _wood(r[:k])+'_door_'+('top' if up else 'bottom')
    for p,s in (('wool_colored_','_wool'),('hardened_clay_stained_','_terracotta'),('concrete_powder_','_concrete_powder'),('concrete_','_concrete'),('glazed_terracotta_','_glazed_terracotta'),('shulker_top_','_shulker_box'),('glass_pane_top_','_stained_glass_pane_top')):
        if n.startswith(p): return _color(n[len(p):])+s
    if n.startswith('glass_') and n!='glass_pane_top': return _color(n[6:])+'_stained_glass'
    return n
